//! Runs the game's Domino mission scripts.
//!
//! Far Cry 3's missions, side activities and much of its scripted behaviour
//! are "Domino" graphs: Lua generated by Ubisoft's visual scripting tool, one
//! file per graph or box (`domino\user\fc3\...` for the game's own content,
//! `domino\system\...` for the boxes that reach into the engine). They run
//! here on an embedded Lua 5.1, with the runtime they expect around them
//! (`prelude.lua`) and the engine functions they call provided by the host
//! through [`Domino::register`]. Calls to functions the host hasn't provided
//! are logged (see [`Domino::take_unknown_calls`]) and return nothing.
//!
//! Values cross as the engine passes them: entity ids are decimal strings of
//! the 64-bit id (a Lua number can't hold one), [`INVALID_ID`] being none;
//! vectors are `{x, y, z}` arrays; callbacks name a box and one of its
//! methods.

use std::cell::RefCell;
use std::rc::Rc;

use mlua::{IntoLuaMulti, Lua, MultiValue, Table, Value};

/// Where the scripts come from (the converted cache, or the game's archives).
pub trait ScriptSource {
    /// A script by the path a graph names it with (`Domino/System/Door.lua`).
    fn script(&self, path: &str) -> Option<String>;
}

/// The entity id that stands for none.
pub const INVALID_ID: &str = "18446744073709551615";

/// What `GetPathID` gives for a path: the archive's hash of it (CRC-64 of the
/// path in lower case with backslashes), as a decimal string.
pub fn path_id(path: &str) -> String {
    fc3_formats::hash::path_hash(&path.replace('/', "\\")).to_string()
}

#[derive(Default)]
struct State {
    /// Unknown natives called, with their arguments.
    unknown: Vec<String>,
    /// Resources graphs asked to load (path, kind).
    resources: Vec<(String, String)>,
    /// The runtime's own log lines (warnings, traces) and missing scripts.
    log: Vec<String>,
}

/// A Lua state running Domino graphs.
pub struct Domino {
    lua: Lua,
    state: Rc<RefCell<State>>,
}

/// A short rendering of a Lua value for logs.
pub fn describe(v: &Value) -> String {
    match v {
        Value::Nil => "nil".into(),
        Value::Boolean(b) => b.to_string(),
        Value::Integer(i) => i.to_string(),
        Value::Number(n) => n.to_string(),
        Value::String(s) => format!("{:?}", s.to_string_lossy()),
        Value::Table(_) => "{..}".into(),
        Value::Function(_) => "fn".into(),
        other => other.type_name().into(),
    }
}

fn describe_all(args: MultiValue) -> Vec<String> {
    args.into_iter()
        .map(|v| match v {
            Value::String(s) => s.to_string_lossy(),
            other => describe(&other),
        })
        .collect()
}

impl Domino {
    pub fn new(source: impl ScriptSource + 'static) -> mlua::Result<Domino> {
        let lua = Lua::new();
        let state = Rc::new(RefCell::new(State::default()));
        let g = lua.globals();
        g.set("GetPathID", lua.create_function(|_, path: String| Ok(path_id(&path)))?)?;
        let source = Rc::new(source);
        let s = state.clone();
        g.set(
            "__domino_load",
            lua.create_function(move |lua, path: String| match source.script(&path) {
                Some(text) => lua.load(text).set_name(path).exec().map(|()| true),
                None => {
                    s.borrow_mut().log.push(format!("missing script {path}"));
                    Ok(false)
                }
            })?,
        )?;
        let s = state.clone();
        g.set(
            "__domino_resource",
            lua.create_function(move |_, (path, kind): (String, Option<String>)| {
                s.borrow_mut().resources.push((path, kind.unwrap_or_default()));
                Ok(())
            })?,
        )?;
        let s = state.clone();
        g.set(
            "__domino_log",
            lua.create_function(move |_, args: MultiValue| {
                let parts = describe_all(args);
                s.borrow_mut().log.push(parts.join(" "));
                Ok(())
            })?,
        )?;
        let s = state.clone();
        g.set(
            "__domino_unknown",
            lua.create_function(move |_, args: MultiValue| {
                let mut parts = describe_all(args).into_iter();
                let name = parts.next().unwrap_or_default();
                let rest: Vec<String> = parts.collect();
                s.borrow_mut().unknown.push(format!("{name}({})", rest.join(", ")));
                Ok(())
            })?,
        )?;
        lua.load(include_str!("prelude.lua")).set_name("prelude").exec()?;
        Ok(Domino { lua, state })
    }

    pub fn lua(&self) -> &Lua {
        &self.lua
    }

    /// Provides a native function the scripts call.
    pub fn register<F, A, R>(&self, name: &str, f: F) -> mlua::Result<()>
    where
        F: Fn(&Lua, A) -> mlua::Result<R> + 'static,
        A: mlua::FromLuaMulti,
        R: mlua::IntoLuaMulti,
    {
        self.lua.globals().raw_set(name, self.lua.create_function(f)?)
    }

    /// Creates an instance of a graph or box with no entity behind it.
    pub fn create(&self, path: &str) -> mlua::Result<Table> {
        self.create_on(path, None, None, None)
    }

    /// Creates the instance of a graph a Domino component runs on an entity
    /// (and the prefab that entity belongs to), its inputs written before
    /// its `Init`, as the engine does.
    pub fn create_on(&self, path: &str, parent: Option<&str>, prefab: Option<&str>, inputs: Option<Table>) -> mlua::Result<Table> {
        let create: mlua::Function = self.lua.globals().get("__domino_create")?;
        create.call((path, parent, prefab, inputs))
    }

    /// Calls a box's method as the engine does (looked up on its class), with
    /// arguments; nothing happens if the class has no such method.
    pub fn call_with(&self, box_: &Table, method: &str, args: impl IntoLuaMulti) -> mlua::Result<MultiValue> {
        let call: mlua::Function = self.lua.globals().get("__domino_call")?;
        let mut all = vec![Value::Table(box_.clone()), Value::String(self.lua.create_string(method)?)];
        all.extend(args.into_lua_multi(&self.lua)?);
        call.call(MultiValue::from_iter(all))
    }

    /// Calls one of a box's inputs (`In`, `Start`, ...).
    pub fn call(&self, box_: &Table, input: &str) -> mlua::Result<()> {
        self.call_with(box_, input, ()).map(|_| ())
    }

    /// The unknown natives called since the last time, with their arguments.
    pub fn take_unknown_calls(&self) -> Vec<String> {
        std::mem::take(&mut self.state.borrow_mut().unknown)
    }

    /// The resources graphs asked to load since the last time (path, kind).
    pub fn take_resources(&self) -> Vec<(String, String)> {
        std::mem::take(&mut self.state.borrow_mut().resources)
    }

    /// The runtime's log lines since the last time (script warnings and
    /// traces, missing scripts).
    pub fn take_log(&self) -> Vec<String> {
        std::mem::take(&mut self.state.borrow_mut().log)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    struct Scripts(HashMap<String, String>);

    impl ScriptSource for Scripts {
        fn script(&self, path: &str) -> Option<String> {
            self.0.get(&path.to_ascii_lowercase()).cloned()
        }
    }

    /// Made-up scripts in the generated ones' shape: a stateful box, a
    /// stateless one, and a graph using both.
    fn scripts() -> Scripts {
        let mut m = HashMap::new();
        m.insert(
            "test/box.lua".into(),
            r#"
            Box = {};
            function Box:Init(cbox) self.count = 0; self.owner = cbox:GetParentEntity() end
            function Box:Fire() self.count = self.count + 1; NativeThing(self.Value); return self:Out() end
            export = Box; Box = nil;
            "#
            .into(),
        );
        m.insert(
            "test/stateless.lua".into(),
            r#"
            S = {};
            function S:Go() NativeThing(self.Value); return self:Out() end
            export = S; S = nil;
            "#
            .into(),
        );
        m.insert(
            "test/graph.lua".into(),
            r#"
            export = {};
            function export:LuaDependencies() return { [1] = "Test/Later.lua" } end;
            function export:Create(cbox)
                if (cbox:ShouldLoadResources() == true) then
                    cbox:RegisterBox("Test/Box.lua");
                    cbox:RegisterBox("Test/Stateless.lua");
                    cbox:RegisterBox("Test/Missing.lua");
                    cbox:LoadResource([[sndres0x00000001]], "CSoundResource");
                end;
            end;
            function export:Init(cbox)
                self.startedWith = self.Target;
                self[1] = cbox:CreateBox("Test/Box.lua");
                self[1]._graph = self;
                self[1].Out = self.f_1_Out;
            end;
            function export:In()
                local l0 = self[1];
                l0.Value = "42";
                l0:Fire();
            end;
            function export:f_1_Out()
                self = self._graph;
                self.done = true;
                local l0 = Boxes[GetPathID("Test/Stateless.lua")];
                l0._graph = self;
                l0.Value = self.startedWith;
                l0.Out = DummyFunction;
                l0:Go();
            end;
            "#
            .into(),
        );
        m.insert("test/later.lua".into(), "export = { loaded = true };".into());
        Scripts(m)
    }

    #[test]
    fn graphs_wire_and_run_their_boxes() {
        let d = Domino::new(scripts()).unwrap();
        let got = Rc::new(RefCell::new(Vec::new()));
        let g = got.clone();
        d.register("NativeThing", move |_, v: Option<String>| {
            g.borrow_mut().push(v);
            Ok(())
        })
        .unwrap();
        let inputs = d.lua().create_table().unwrap();
        inputs.set("Target", "7").unwrap();
        let graph = d.create_on("Test/Graph.lua", Some("123"), None, Some(inputs)).unwrap();
        d.call(&graph, "In").unwrap();
        assert!(graph.get::<bool>("done").unwrap());
        // The graph's own instance, then the stateless class with the input
        // the graph was given before its Init.
        assert_eq!(*got.borrow(), vec![Some("42".to_string()), Some("7".to_string())]);
        let child: Table = graph.get(1).unwrap();
        assert_eq!(child.get::<String>("owner").unwrap(), "123");
        assert_eq!(d.take_resources(), vec![("sndres0x00000001".to_string(), "CSoundResource".to_string())]);
        // A missing dependency is logged, not fatal; data dependencies load.
        assert_eq!(d.take_log(), vec!["missing script Test/Missing.lua".to_string()]);
        let later: Table = d.lua().load(r#"return Boxes[GetPathID("Test/Later.lua")]"#).eval().unwrap();
        assert!(later.get::<bool>("loaded").unwrap());
    }

    #[test]
    fn unknown_natives_are_logged() {
        let d = Domino::new(scripts()).unwrap();
        let graph = d.create("Test/Graph.lua").unwrap();
        d.call(&graph, "In").unwrap();
        let calls = d.take_unknown_calls();
        assert_eq!(calls[0], "NativeThing(42)");
    }

    #[test]
    fn engine_calls_skip_missing_methods() {
        let d = Domino::new(scripts()).unwrap();
        let graph = d.create("Test/Graph.lua").unwrap();
        d.call(&graph, "OnLeaveZone").unwrap();
    }

    /// The id the game gives `Domino/System/Print_v2.lua`.
    #[test]
    fn path_ids_are_archive_hashes() {
        assert_eq!(path_id("Domino/System/Print_v2.lua"), "8578475447439923801");
        assert_eq!(path_id("Domino/System/Door.lua"), path_id(r"domino\system\door.lua"));
    }
}
